# No liked song found in the first playlist.
# I will check other playlists to find the first liked song.
liked_song_in_playlist = None
for playlist in playlist_library:
    playlist_song_ids = playlist.get("song_ids", [])
    for song_id in playlist_song_ids:
        if song_id in liked_song_ids:
            liked_song_in_playlist = song_id
            break
    if liked_song_in_playlist is not None:
        break

print(liked_song_in_playlist)

# No liked song found in the first playlist.
# Let's try to find the first liked song in any playlist by iterating over all playlists and their songs.
liked_song_in_any_playlist = None
for playlist in playlist_library:
    for song_id in playlist.get("song_ids", []):
        if song_id in liked_song_ids:
            liked_song_in_any_playlist = song_id
            break
    if liked_song_in_any_playlist is not None:
        break

print(liked_song_in_any_playlist)

