steps.code:
# The search_songs API returns the release_date directly in the song details.
# So I do not need to call show_album separately.
# I will now write code to get release month info for all songs missing it by searching each song with title and artist.
from datetime import datetime

def get_release_month(release_date_str):
    # release_date_str example: "2022-12-11T06:22:44"
    dt = datetime.fromisoformat(release_date_str)
    return dt.strftime("%m/%Y")

release_months = {}
for song_title, artists in songs_to_update:
    query = f"{song_title} {artists}"
    search_results = apis.spotify.search_songs(query=query, page_index=0, page_limit=1)
    if search_results:
        release_date = search_results[0].get("release_date")
        if release_date:
            release_months[(song_title, artists)] = get_release_month(release_date)
        else:
            release_months[(song_title, artists)] = "UNKNOWN"
    else:
        release_months[(song_title, artists)] = "UNKNOWN"

print(release_months)  # Dictionary with (song_title, artists) as key and release month as value.

